def create_daily_schedules(apps, schema_editor):
    Evento=apps.get_model('clinica','EventoClinica')
    Jornada=apps.get_model('clinica','JornadaEvento')
    alias=schema_editor.connection.alias
    for event in Evento.objects.using(alias).all():
        count=(event.fecha_fin-event.fecha_inicio).days+1
        for i in range(count):
            Jornada.objects.using(alias).create(evento=event,fecha=event.fecha_inicio+timedelta(days=i),
                estado='Cerrada' if event.estado=='Finalizado' else 'Abierta' if i==0 and event.estado=='En curso' else 'Pendiente')


